INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 0, 'theory', 'Квиз: язык программирования и Питон');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 0, 'Что такое язык программирования?', '["Набор клавиш на клавиатуре","Посредник, на котором договариваются человек и процессор","Программа для рисования","Только язык для сайтов"]', 1, 'Процессор понимает лишь числовые команды, а человек думает образами — язык программирования позволяет описать задачу понятно человеку и точно для машины.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 1, 'Чем интерпретатор отличается от компилятора?', '["Интерпретатор читает и выполняет программу по шагам, компилятор заранее переводит её целиком","Они ничем не отличаются","Интерпретатор работает только на сервере","Компилятор не умеет выдавать ошибки"]', 0, 'Питон выполняет интерпретатор: набрал строку — сразу результат. Компилятор (как у C и Rust) сначала собирает программу, а потом её запускают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 2, 'Почему Питон хорошо подходит для первого языка?', '["Он самый быстрый на свете","В нём нет ошибок","Он читается почти как английский, популярен и имеет богатую стандартную библиотеку","Он годится только для детей"]', 2, 'Низкий порог входа, читаемость, большое сообщество и «батарейки в комплекте» дают быстрый старт без потери серьёзных возможностей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 3, 'Какая пара областей применения Питона названа верно?', '["Только игры и дизайн","Веб-разработка и машинное обучение","Только написание драйверов","Только бухгалтерия"]', 1, 'Питон пишут серверные части сайтов (Django, FastAPI), обучают на нём нейросети (NumPy, PyTorch) и автоматизируют рутину; встречается и в утилитах операционных систем.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 0, 4, 'Для чего нужна функция в программировании?', '["Чтобы раскрасить текст","Чтобы выключить компьютер","Чтобы хранить картинки","Чтобы собрать набор действий под одним именем и вызывать его много раз"]', 3, 'Функция избавляет от повторений: описали один раз — вызываем сколько нужно; у неё есть параметры на входе и результат на выходе.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 1, 'theory', 'Квиз: первая программа');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 0, 'Что делает команда print?', '["Печатает текст на бумаге","Показывает переданное ей значение на экране","Сохраняет значение в файл","Запускает программу"]', 1, 'print печатает на экран — никакой бумаги: имя осталось от эпохи принтеров.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 1, 'Какие кавычки годятся для строки в Python?', '["Только одинарные","Только двойные","Одинарные и двойные — главное одинаковые с обеих сторон","Вообще без кавычек"]', 2, 'Одинарные и двойные равноправны; важно, чтобы ограда совпадала с обеих сторон.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 2, 'В программе три команды print подряд. В каком порядке они выполнятся?', '["Сверху вниз, по одной строке за раз","Снизу вверх","В случайном порядке","Все одновременно"]', 0, 'Программа — рецепт: машина читает команды по одной, сверху вниз.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 3, 'Что сделает Python со строкой после символа #?', '["Выполнит её первым","Полностью проигнорирует","Покажет её на экране","Сообщит об ошибке"]', 1, 'Всё после решётки в строке — комментарий: заметка для людей, не для машины.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 4, 'print(''2 + 2'') и print(2 + 2) — что напечатают?', '["Оба напечатают 4","Оба напечатают 2 + 2","Первый — 2 + 2, второй — 4","Первый — 4, второй — 2 + 2"]', 2, 'В кавычках — просто текст, без них — арифметика, которую Python посчитает.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 2, 'theory', 'Квиз: переменные и типы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 0, 'Как правильно читать строку count = 5?', '["count равно пяти","Положить значение 5 в коробку с именем count","Сравнить count и 5","Проверить, что count — это 5"]', 1, 'Знак равенства здесь присваивание: сначала вычисляется правая часть, потом кладётся в коробку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 1, 'Какое имя переменной запрещено?', '["user_count","count2","2count","_temp"]', 2, 'Имя не может начинаться с цифры. Буквы, цифры и подчёркивание — можно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 2, 'age и Age — это одна переменная или разные?', '["Одна: регистр не важен","Разные: регистр важен","Python выдаст ошибку за похожие имена","Зависит от версии Python"]', 1, 'Регистр важен: age и Age — две разные коробки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 3, 'Что вернёт len(''привет'')?', '["5","6","7","Ошибку: len работает только с числами"]', 1, 'len возвращает число символов строки, включая пробелы: здесь их шесть.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 4, 'Что произойдёт при вычислении «5» + 5?', '["Получится 10","Получится «55»","Ошибка типов: Python не угадывает, что имелось в виду","Получится «5 5»"]', 2, 'Строка и число не складываются. Нужно преобразование: int(''5'') + 5 или ''5'' + str(5).');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 3, 'theory', 'Квиз: условия');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 0, 'Чем проверка равенства отличается от присваивания?', '["Ничем, это одно и то же","Присваивание — один знак =, проверка — два знака ==","Проверка — один знак =, присваивание — ==","В Python проверка делается словом eq"]', 1, 'Один знак — «положить», два знака — вопрос «равны ли». Перепутать — классическая ошибка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 1, 'Зачем в Python отступ внутри if?', '["Это украшение для читаемости","Так требует редактор кода","Отступ — часть языка: он показывает, что код относится к условию","Отступ ускоряет программу"]', 2, 'В Python отступ — синтаксис: блок с отступом выполняется, когда условие истинно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 2, 'В цепочке if / elif / elif / else сколько веток выполнится?', '["Все, где условие истинно","Ровно одна — первая совпавшая","Последняя совпавшая","Две: первая и последняя"]', 1, 'Проверки идут сверху вниз: сработала первая подходящая — остальные даже не рассматриваются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 3, 'Условие «температура больше 30 И в выходной» на Python записывается…', '["t > 30 & weekend","t > 30 and weekend","t > 30 or weekend","t > 30, weekend"]', 1, '«И» — оба условия истинны; пишется словом and.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 3, 4, 'Что вернёт сравнение 0 <= x <= 100 при x = 50?', '["Ошибку: так писать нельзя","False","True: цепочки сравнений работают как в математике","50"]', 2, 'Питон-особенность: цепочку сравнений можно писать одним выражением, как в школе.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 4, 'theory', 'Квиз: функции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 0, 'Что произойдёт, если только описать функцию def hello(): print("Привет") и больше ничего не писать?', '["Напечатается «Привет» один раз","Ничего не напечатается: описание не выполняет тело","Питон выдаст ошибку","Напечатается «Привет» дважды"]', 1, 'Описание только запоминает код под именем; тело выполняется при вызове hello().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 1, 'def f(x): print(x * 2). Чему равно r после r = f(4)?', '["8","None","4","Ошибка"]', 1, 'Функция напечатала 8, но не вернула ничего: без return результат — None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 2, 'Вызов square(5). Как называется значение 5?', '["Параметр","Аргумент","Результат","Ключ"]', 1, 'Параметр — имя в описании функции, аргумент — конкретное значение при вызове.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 3, 'def power(x, n=2): return x ** n. Что вернёт power(3)?', '["6","9","27","Ошибку: не хватает аргумента"]', 1, 'n не передали — берётся значение по умолчанию 2: 3 ** 2 = 9.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 4, 4, 'Что случится при print(local), если переменная local создана только внутри функции?', '["Напечатается её значение","Напечатается None","NameError: снаружи имя неизвестно","Питон создаст переменную сам"]', 2, 'Локальные переменные живут только внутри функции; после её завершения они исчезают.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 5, 'theory', 'Квиз: циклы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 0, 'Чем цикл for отличается от while?', '["Ничем, это синонимы","for — «для каждого элемента из», while — «пока условие истинно»","while работает только с числами","for всегда быстрее"]', 1, 'for — когда известно, по чему идём; while — когда повторяем, пока не случится событие.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 1, 'Сколько раз выполнится тело цикла: for i in range(3)?', '["2","3","4","Бесконечно"]', 1, 'range(3) даёт числа 0, 1, 2 — три витка. Правая граница не включается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 2, 'Что делает break внутри цикла?', '["Пропускает один виток","Немедленно выходит из цикла","Перезапускает цикл с начала","Останавливает всю программу"]', 1, 'break прерывает цикл целиком: выполнение продолжается после него.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 3, 'Что делает continue?', '["Выходит из цикла","Пропускает остаток тела и переходит к следующему витку","Начинает цикл заново с новым условием","Ничего не делает — заглушка"]', 1, 'continue пропускает только текущий виток, цикл продолжается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 4, 'Сколько чисел напечатает for i in range(2, 10, 3)?', '["2","3","4","8"]', 1, 'Шаг три от двойки: 2, 5, 8 — дальше 11, а граница 10 уже пройдена. Итого три числа.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 6, 'theory', 'Квиз: списки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 6, 0, 'items = ["а", "б", "в"]. Что вернёт items[0]?', '["\"а\"","\"б\"","Ошибку","\"в\""]', 0, 'Нумерация с нуля: первый элемент — индекс 0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 6, 1, 'Как взять последний элемент списка, не зная его длины?', '["items[0]","items[-1]","items[last]","items.len"]', 1, 'Отрицательные индексы считают с конца: -1 — последний, -2 — предпоследний.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 6, 2, 'Как добавить элемент в конец списка?', '["items.add(x)","items.append(x)","items + x","push(items, x)"]', 1, 'Метод append добавляет элемент в конец — список растёт на ходу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 6, 3, 'Что вернёт len([10, 20, 30])?', '["2","3","30","60"]', 1, 'len возвращает число элементов — здесь три.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 6, 4, 'Что вернёт срез [1, 2, 3, 4][1:3]?', '["[1, 2]","[2, 3]","[2, 3, 4]","[1, 2, 3]"]', 1, 'Срез берёт от индекса 1 включительно до 3 не включительно — та же логика, что у range.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 7, 'theory', 'Квиз: перебор и копирование списков');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 0, 'Что получит первая пара при переборе for i, x in enumerate(["а", "б"], start=1)?', '["i = 0, x = \"а\"","i = 1, x = \"б\"","i = 1, x = \"а\"","i = 0, x = \"б\""]', 2, 'enumerate отдаёт пары «номер, элемент»; start=1 начинает счёт с единицы, а первый элемент — «а».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 1, 'Сколько витков сделает цикл for a, b in zip([1, 2, 3], [10, 20])?', '["3","2","5","Упадёт с ошибкой"]', 1, 'zip останавливается на самом коротком списке — лишний элемент длинного молча отбрасывается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 2, 'a = [1, 2, 3]; b = a; b.append(4). Чему равен список a?', '["[1, 2, 3, 4]","[1, 2, 3]","[4]","Ошибка"]', 0, 'b = a не копирует: у одного списка просто два имени, поэтому правка через b видна и в a.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 3, 'Какая запись создаёт настоящую (независимую) копию списка a?', '["b = a","b = [a]","b = a is a","b = a[:]"]', 3, 'Полный срез a[:] (как и a.copy() и list(a)) строит новый список; b = a лишь вешает второе имя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 7, 4, 'grid = [[0] * 3] * 3; grid[0][0] = 7. Чему равно grid[1][0]?', '["0","7","None","Ошибка"]', 1, 'Внешнее умножение повторило ссылку на одну и ту же строку, поэтому изменились все три строки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 8, 'theory', 'Квиз: сортировка и генераторы списков');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 0, 'nums = [3, 1, 2]; sorted(nums). Чему равен список nums после этого?', '["[1, 2, 3]","[3, 2, 1]","[3, 1, 2]","None"]', 2, 'sorted возвращает новый список, а исходный не трогает — в отличие от метода sort.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 1, 'Что окажется в nums после записи nums = nums.sort()?', '["Отсортированный список","None","Пустой список","Ошибка при запуске"]', 1, 'sort меняет список на месте и возвращает None — присваивание затирает список пустотой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 2, 'Что делает параметр key в sorted(words, key=len)?', '["Сортирует по длине списка words","Оставляет только слова длиной len","Сортирует по значению, которое функция len вычислила для каждого элемента","Сортирует по алфавиту"]', 2, 'key — функция, которую Python применяет к каждому элементу; порядок строится по её результатам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 3, 'Что вернёт [x for x in [1, 2, 3, 4] if x > 2]?', '["[1, 2]","[3, 4]","[False, False, True, True]","[1, 2, 3, 4]"]', 1, 'Условие в конце генератора отбирает элементы: в результат попадают только 3 и 4.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 4, 'Что вернут any([]) и all([]) для пустого списка?', '["False и True","True и True","False и False","True и False"]', 0, 'Подходящих элементов нет — any даёт False; нарушителей тоже нет — all даёт True.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 9, 'theory', 'Квиз: словари');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 0, 'prices = {"яблоко": 50}. Что вернёт prices.get("киви", 0)?', '["Ошибку KeyError","None","0","50"]', 2, 'get не падает на отсутствующем ключе и возвращает запасное значение — здесь 0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 1, 'prices = {"яблоко": 50}. Что вернёт 50 in prices?', '["True","False","Ошибку","50"]', 1, 'Слово in у словаря проверяет ключи, а 50 — значение. Для значений нужно 50 in prices.values().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 2, 'Что произойдёт при prices["киви"] = 90, если ключа "киви" в словаре ещё нет?', '["Питон выдаст ошибку ключа","В словаре появится новая пара","Перезапишется первая пара","Ничего не изменится"]', 1, 'Присваивание по ключу и добавляет новую пару, и заменяет значение существующей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 3, 'Какая запись правильно считает частоты слов w в словаре counts?', '["counts[w] = counts[w] + 1","counts[w] += 1 без создания ключа","counts[w] = counts.get(w, 0) + 1","counts.add(w)"]', 2, 'Первые две записи упадут на новом слове с ошибкой ключа; get с нулём создаёт пару при первой встрече.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 9, 4, 'Что нельзя использовать в качестве ключа словаря?', '["Строку","Число","Кортеж","Список"]', 3, 'Ключ должен быть неизменяемым: список меняется на месте, поэтому Питон отвечает TypeError: unhashable.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 10, 'theory', 'Квиз: приёмы со словарями');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 0, 'a = {"x": 1, "y": 2}; b = {"y": 20}. Чему равно a | b?', '["{\"x\": 1, \"y\": 2}","{\"x\": 1, \"y\": 20}","{\"y\": 20}","Ошибка: нельзя слить"]', 1, 'При совпадении ключа побеждает правый словарь, остальные пары сохраняются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 1, 'Что вернёт dict(zip(["a", "b"], [1, 2]))?', '["{\"a\": 1, \"b\": 2}","[(\"a\", 1), (\"b\", 2)]","{1: \"a\", 2: \"b\"}","Ошибку"]', 0, 'zip склеивает элементы по парам, dict превращает пары в словарь «первый — ключ, второй — значение».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 2, 'Что делает groups.setdefault(key, []).append(x)?', '["Всегда заменяет список под ключом пустым","Добавляет x в список под ключом, создав пустой список, если ключа не было","Падает с ошибкой, если ключа нет","Удаляет ключ из словаря"]', 1, 'setdefault возвращает существующее значение или кладёт и возвращает запасное — поэтому сразу можно делать append.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 3, 'sales = {"чай": 5, "кофе": 9}. Что вернёт max(sales, key=sales.get)?', '["\"чай\"","\"кофе\"","9","5"]', 1, 'max перебирает ключи, а key=sales.get сравнивает их по значениям: наибольшее у «кофе». Возвращается ключ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 10, 4, 'shared = dict.fromkeys(["а", "б"], []); shared["а"].append(1). Чему равно shared["б"]?', '["[]","[1]","None","Ошибка ключа"]', 1, 'fromkeys кладёт под все ключи один и тот же список — это ссылки, а не копии.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 11, 'theory', 'Квиз: кортежи');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 0, 'Что создаёт кортеж из одного элемента?', '["(1)","[1]","(1,)","{1}"]', 2, 'Кортеж создаёт запятая: (1) — просто число в скобках, а (1,) — кортеж из одного элемента.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 1, 't = (1, 2, 3). Что произойдёт при t[0] = 99?', '["t станет (99, 2, 3)","Питон выдаст TypeError: кортеж нельзя менять","Добавится четвёртый элемент","Ничего"]', 1, 'Кортеж неизменяем: присваивание по индексу невозможно. Изменить его можно только пересборкой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 2, 'a, b = 1, 2; a, b = b, a. Чему равны a и b?', '["a = 1, b = 2","a = 2, b = 1","a = 2, b = 2","Ошибка"]', 1, 'Правая часть собирается целиком до присваивания, поэтому значения обмениваются без временной переменной.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 3, 'Что вернёт функция с записью return min(nums), max(nums)?', '["Список из двух чисел","Только минимум","Кортеж из двух чисел","Словарь"]', 2, 'Запятая в return собирает кортеж; вызывающий код может сразу распаковать его в две переменные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 4, 'Что получится у first, *rest = [10, 20, 30]?', '["first = 10, rest = [20, 30]","first = [10], rest = 20","first = 10, rest = (20, 30)","ValueError"]', 0, 'Звёздочка собирает все лишние элементы в список: в first — начало, в rest — остальное.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 12, 'theory', 'Квиз: классы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 0, 'class Dog: pass; d = Dog(). Что такое d?', '["Класс Dog","Экземпляр (объект) класса Dog","Функция","Атрибут класса"]', 1, 'Класс — чертёж, а d — объект, созданный по нему: экземпляр класса Dog.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 1, 'Когда Питон вызывает метод __init__?', '["При удалении объекта","При каждом вызове любого метода","Автоматически при создании экземпляра","Только если вызвать его вручную"]', 2, '__init__ — конструктор: его вызывает сам Питон при Dog(...) и передаёт аргументы из скобок.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 2, 'a = Counter(); b = a; b.inc(). Что произошло со счётчиком a?', '["Не изменился: b — копия","Увеличился: a и b — один и тот же объект","Питон выдал ошибку","Создался третий счётчик"]', 1, 'Присваивание не копирует объект: у одного экземпляра появилось второе имя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 3, 'class A: items = []. x, y = A(), A(); x.items.append(1). Чему равно y.items?', '["[]","[1]","None","Ошибка"]', 1, 'Список объявлен на уровне класса, поэтому он общий для всех экземпляров. Изменяемые данные создают в __init__.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 4, 'Что случится при вызове A().hello(), если метод описан как def hello(): ... (без self)?', '["Всё сработает","TypeError: метод получил лишний аргумент","NameError","Питон добавит self сам"]', 1, 'Питон передаёт объект первым аргументом, а в описании параметра для него нет.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 13, 'theory', 'Квиз: методы и свойства');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 0, 'Какой метод вызывает Питон на a при выполнении a + b?', '["a.__plus__(b)","a.__add__(b)","a.add(b)","b.__add__(a)"]', 1, 'Оператор + — запись вызова магического метода __add__ у левого операнда.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 1, 'Вы описали __eq__, но не описали __hash__. Что произойдёт при {obj: 1}?', '["Всё сработает","TypeError: unhashable type","Объект будет сравниваться по id","Питон сам добавит __hash__"]', 1, 'Если определён __eq__ и не определён __hash__, Питон отключает хеширование: объект нельзя брать в ключи.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 2, 'Что делает декоратор @property над методом area?', '["Делает метод приватным","Позволяет читать area как атрибут, без скобок","Запрещает менять объект","Ускоряет метод"]', 1, 'Свойство выглядит как атрибут: obj.area вместо obj.area(); значение вычисляется при обращении.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 3, 'Для чего чаще всего нужен @classmethod?', '["Для скрытых данных","Для альтернативных конструкторов, например from_string","Для сортировки","Чтобы метод вызывался быстрее"]', 1, 'Метод класса получает cls и возвращает новый объект другим способом, чем основной конструктор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 13, 4, 'Что нужно описать в классе, чтобы sorted(list_of_objects) работал без параметра key?', '["__len__","__lt__","__str__","__hash__"]', 1, 'sorted сравнивает элементы оператором <, то есть методом __lt__.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 14, 'theory', 'Квиз: наследование и композиция');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 0, 'class Dog(Animal): ... Что вернёт isinstance(Dog(), Animal)?', '["False","True","Ошибку","None"]', 1, 'Dog — наследник Animal, поэтому собака является животным.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 1, 'Зачем в __init__ наследника вызывают super().__init__(...)?', '["Чтобы удалить родителя","Чтобы родительский конструктор создал общие атрибуты","Чтобы ускорить создание объекта","Это необязательный стиль"]', 1, 'Без этого вызова общие атрибуты родителя не появятся, и объект будет недособранным.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 2, 'Автомобиль хранит внутри объект Engine как атрибут. Как называется такая связь?', '["Наследование","Композиция","Полиморфизм","Инкапсуляция"]', 1, 'Композиция выражает «имеет»: автомобиль имеет двигатель, но не является им.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 3, 'Что произойдёт при создании экземпляра абстрактного класса с нереализованным @abstractmethod?', '["Объект создастся","TypeError","Вызовется пустой метод","NameError"]', 1, 'Абстрактный класс — шаблон: пока не реализованы все абстрактные методы, создать экземпляр нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 4, 'd = Dog(); класс Dog наследует Animal. Чему равно type(d) is Animal?', '["True","False","Ошибка","None"]', 1, 'type возвращает точный класс — это Dog; иерархию учитывает isinstance, а не type.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 15, 'theory', 'Квиз: исключения');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 0, 'В какой строке трассировки находится самая важная информация об ошибке?', '["В первой","В самой нижней: тип и сообщение ошибки","В середине","Такой строки нет"]', 1, 'Трассировку читают снизу вверх: последняя строка называет тип ошибки и сообщение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 1, 'try: int("abc") / except ValueError: print("x") / else: print("y") / finally: print("z"). Что напечатается?', '["x и z","y и z","только x","x, y и z"]', 0, 'Ошибка была — сработал except (x); else не выполняется; finally выполняется всегда (z).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 2, 'Что делает голый raise внутри блока except?', '["Создаёт новую пустую ошибку","Пропускает то же исключение дальше, сохранив трассировку","Останавливает интерпретатор","Ничего"]', 1, 'raise без аргументов повторно поднимает пойманное исключение вместе со всей трассировкой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 3, 'Как создать собственное исключение?', '["def MyError(): ...","class MyError(Exception): pass","raise MyError","import MyError"]', 1, 'Собственное исключение — обычный класс-наследник Exception.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 4, 'Почему данные от пользователя нельзя проверять через assert?', '["assert медленный","assert отключается при запуске с оптимизацией","assert не поднимает ошибок","assert работает только с числами"]', 1, 'Запуск python -O убирает все assert; проверку входных данных делают через raise с настоящим исключением.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 16, 'theory', 'Квиз: файлы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 0, 'Что произойдёт с существующим файлом при open("a.txt", "w")?', '["Откроется для чтения","Содержимое будет стёрто сразу при открытии","Данные допишутся в конец","Питон выдаст ошибку"]', 1, 'Режим w открывает файл на запись и очищает его сразу, даже если вы ничего не запишете.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 1, 'Зачем писать with open(...) as f?', '["Чтобы файл читался быстрее","Чтобы файл закрылся автоматически, даже если случится ошибка","Чтобы получить байты","Это обязательно для чтения"]', 1, 'with — контекстный менеджер: при выходе из блока он закрывает файл в любом случае.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 2, 'Как прочитать файл любого размера, не загружая его целиком в память?', '["f.read()","f.readlines()","for line in f","list(f.read())"]', 2, 'Цикл по файлу отдаёт по одной строке; в памяти лежит только текущая.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 3, 'f.write("привет"); f.write("мир"). Что окажется в файле?', '["привет и мир на двух строках","приветмир одной строкой","только мир","Ошибка"]', 1, 'write не добавляет перевод строки: если он нужен, его дописывают самим.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 16, 4, 'Что нужно указать для текстового файла, чтобы русские буквы читались одинаково на любой системе?', '["mode=\"r\"","encoding=\"utf-8\"","newline=True","bytes=False"]', 1, 'Кодировку лучше всегда задавать явно: по умолчанию она зависит от системы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 17, 'theory', 'Квиз: пути и форматы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 0, 'Чему соответствует Path("data") / "a.txt"?', '["Делению объекта на строку: ошибка","Объекту пути data/a.txt","Строке «data a.txt»","Числу"]', 1, 'Слэш у объектов Path склеивает части; результат — снова путь, а не строка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 1, 'Что вернёт json.dumps({1: ''a''})?', '["{1: \"a\"}","{\"1\": \"a\"}","[1, ''a'']","Ошибку"]', 1, 'Ключи объектов JSON всегда строки, поэтому число 1 превращается в «1».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 2, 'csv.DictReader прочитал строку: {"возраст": "20"}. Какого типа значение "20"?', '["int","str","float","bool"]', 1, 'Из CSV все значения приходят строками; числа нужно переводить самим.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 3, 'Зачем при записи файла сначала пишут во временный файл, а потом делают os.replace?', '["Так быстрее","Замена выполняется целиком: сбой не оставит наполовину испорченный файл","Так меньше места","Это требование JSON"]', 1, 'Переименование на уровне системы либо выполнено полностью, либо нет — данные не теряются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 4, 'Почему нельзя загружать pickle из чужих файлов?', '["Он слишком медленный","Загрузка может выполнить произвольный код","Он не поддерживает числа","Он хранит только строки"]', 1, 'pickle восстанавливает объекты, выполняя код из файла: чужой файл может быть вредоносным.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 18, 'theory', 'Квиз: специальные методы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 0, 'Что на самом деле происходит при вызове len(obj)?', '["Питон считает атрибуты объекта","Питон читает obj.__dict__","Питон вызывает type(obj).__len__(obj)","Питон вызывает obj.length()"]', 2, 'Встроенная функция — лишь фасад: интерпретатор находит у типа объекта метод __len__ и вызывает его.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 1, 'Что покажет print(obj), если в классе есть и __str__, и __repr__?', '["Результат __repr__","Результат __str__","Обе строки подряд","Результат __format__"]', 1, 'print и f-строки берут __str__; __repr__ используют консоль, содержимое списков и !r.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 2, 'Вы написали __eq__, но не написали __hash__. Что с объектом?', '["Хеш считается по id, как раньше","Питон выдаст ошибку при определении класса","Хеш берётся от результата __eq__","Объект станет нехешируемым: в множество или ключ словаря его не положить"]', 3, 'Равные объекты обязаны иметь равный хеш, поэтому при определении __eq__ Питон сам обнуляет __hash__.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 3, 'Что вернуть из __lt__, если метод не умеет сравнивать с чужим типом?', '["NotImplemented","False","None","Поднять ValueError"]', 0, 'NotImplemented даёт Питону шанс попробовать отражённую операцию второго операнда; потом он сам поднимет TypeError.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 18, 4, 'Когда вызывается __getattr__?', '["При каждом обращении к любому атрибуту","Только когда обычный поиск не нашёл имя","При записи атрибута","При создании объекта"]', 1, '__getattr__ — запасной ход после неудачного поиска; при каждом обращении вызывается __getattribute__.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 19, 'theory', 'Квиз: перегрузка операторов');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 0, 'Во что превращается выражение a + b?', '["В type(a).__add__(a, b)","В a.add(b)","В __plus__(b, a)","В b.__add__(a)"]', 0, 'Сначала вызывается метод сложения левого операнда; отражённый метод правого — только если левый вернул NotImplemented.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 1, 'Что произойдёт при 3 * v, если у Vector есть __mul__, но нет __rmul__?', '["Вернётся вектор, умноженный на 3","int вызовет Vector.__mul__","Питон поменяет операнды сам и всё получится","TypeError: int не умеет умножаться на Vector"]', 3, 'int.__mul__ вернёт NotImplemented, а у Vector нет отражённого метода, поэтому операция не поддерживается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 2, 'Что обязан вернуть метод __iadd__?', '["None","self","Новый объект того же типа","Число"]', 1, 'Результат __iadd__ записывается обратно в переменную: без return self там окажется None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 3, 'Зачем встроенной sum() нужен __radd__ у вашего класса?', '["sum() переставляет слагаемые местами","sum() вызывает __iadd__","Она начинает с 0: сначала считается 0 + первый_элемент","Без него sum() вернёт 0"]', 2, 'sum(items) — это 0 + item1 + item2…, поэтому класс должен уметь стоять справа от числа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 4, 'Чем __index__ отличается от __int__?', '["Ничем, это синонимы","__index__ обязан быть точным целым и нужен индексам, срезам, hex() и range()","__index__ работает только со строками","__int__ нужен для срезов"]', 1, '__int__ может терять данные (int(3.9)), а __index__ говорит, что объект целое по природе — поэтому у float его нет.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 20, 'theory', 'Квиз: контейнеры, вызов и with');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 0, 'Какую ошибку должен поднять __getitem__ последовательности, когда индекса нет?', '["KeyError","IndexError","ValueError","StopIteration"]', 1, 'По IndexError Питон понимает, что последовательность кончилась, — именно на этом работает перебор без __iter__.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 1, 'Что получит __getitem__, когда вы пишете items[1:3]?', '["Кортеж (1, 3)","Список [1, 2]","Объект slice(1, 3, None)","Два аргумента: 1 и 3"]', 2, 'Срез приходит одним ключом — объектом slice; метод indices(len) даёт готовые границы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 2, 'Почему наследование от dict с переопределением __setitem__ ненадёжно?', '["dict запрещает наследование","Встроенные методы вроде update не вызывают ваш __setitem__","__setitem__ нельзя переопределять","Класс станет нехешируемым"]', 1, 'dict написан на C и обновляет таблицу напрямую; для переопределений используйте UserDict или Mapping.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 3, 'Что произойдёт, если __exit__ вернёт True?', '["Выход повторится","Исключение блока with будет подавлено","Объект закроется дважды","Исключение полетит дальше"]', 1, 'Истинное значение из __exit__ сообщает, что ошибка обработана; иначе исключение продолжит путь.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 4, 'Что выведет callable(Multiplier(3)), если у Multiplier есть __call__?', '["False","None","Ошибку","True"]', 3, 'Экземпляр с __call__ вызывается как функция, а callable() проверяет именно это.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 21, 'theory', 'Квиз: дескрипторы, property и slots');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 0, 'Что такое дескриптор?', '["Декоратор для функций","Атрибут с двойным подчёркиванием","Объект в атрибуте класса с методами __get__, __set__ или __delete__","Словарь атрибутов экземпляра"]', 2, 'Дескриптор получает управление, когда к атрибуту обращаются через экземпляр; property, методы и слоты — готовые дескрипторы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 1, 'Откуда берётся self при вызове obj.method()?', '["Функция в классе — дескриптор: её __get__ возвращает связанный метод с запомненным obj","Питон копирует объект","self — зарезервированное слово","Каждый метод хранит ссылку на экземпляр с самого рождения"]', 0, 'Через экземпляр function.__get__ создаёт связанный метод и подставляет obj первым аргументом; через класс — возвращает функцию как есть.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 2, 'Где нужно хранить значение, которое проверяет дескриптор данных?', '["В самом дескрипторе","В глобальном словаре","В атрибуте класса","В экземпляре, например в obj.__dict__"]', 3, 'Дескриптор один на весь класс, поэтому значение в нём стало бы общим для всех экземпляров.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 3, 'Почему cached_property не вызывает функцию второй раз?', '["Питон запоминает аргументы вызова","Результат записан в obj.__dict__, а дескриптор без данных слабее словаря","Функция удаляется после первого вызова","Он блокирует повторные вызовы"]', 1, 'Поиск находит значение в словаре экземпляра раньше, чем доходит до дескриптора без данных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 4, 'Что произойдёт при p.z = 3, если в Point есть __slots__ = (''x'', ''y'') и нет родителей со словарём?', '["Появится новый атрибут z","AttributeError","Значение попадёт в __dict__","Присваивание молча проигнорируется"]', 1, 'Слоты фиксируют набор полей и отключают __dict__, поэтому новые атрибуты добавить нельзя.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 22, 'theory', 'Квиз: итераторы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 0, 'Что вернёт iter([1, 2, 3])?', '["Список [1, 2, 3]","Итератор по этому списку","Число 1","Ошибку"]', 1, 'iter возвращает итератор: объект, который помнит позицию и выдаёт значения через next.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 1, 'Что делает цикл for, когда итератор исчерпан?', '["Падает с ошибкой","Ловит StopIteration и тихо выходит из цикла","Начинает сначала","Возвращает None"]', 1, 'StopIteration — сигнал «элементы закончились»; for перехватывает его сам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 2, 'it = iter([1, 2, 3]); list(it); list(it). Что вернёт второй вызов?', '["[1, 2, 3]","[]","Ошибку","None"]', 1, 'Итератор одноразовый: после первого прохода он исчерпан и второй раз даёт пустой результат.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 3, 'Что нужно описать в классе, чтобы он стал итератором?', '["__len__ и __getitem__","__iter__ и __next__","__enter__ и __exit__","__init__ и __str__"]', 1, 'Протокол итератора: __iter__ возвращает объект, а __next__ выдаёт значение или поднимает StopIteration.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 4, 'Какие из объектов — итераторы, а не просто итерируемые?', '["list и tuple","range и str","открытый файл и результат zip","dict и set"]', 2, 'Файл и zip идут один раз вперёд; список, кортеж, строка и range можно перебирать многократно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 23, 'theory', 'Квиз: генераторы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 0, 'Что произойдёт при вызове генераторной функции def g(): yield 1; print(''x'')?', '["Напечатается x","Вернётся объект-генератор, тело ещё не выполняется","Вернётся число 1","Ошибка"]', 1, 'Вызов только создаёт генератор: код выполняется порциями при запросах next.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 1, 'g = (x * x for x in range(3)); list(g); list(g). Что вернёт второй list?', '["[0, 1, 4]","[]","Ошибку","None"]', 1, 'Генераторное выражение одноразовое: после первого прохода генератор исчерпан.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 2, 'Чем yield отличается от return?', '["Ничем","yield отдаёт значение и приостанавливает функцию, помня состояние","yield завершает программу","return работает только в генераторах"]', 1, 'После yield выполнение продолжится с того же места при следующем next.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 3, 'Что делает yield from flat(x)?', '["Возвращает список из flat(x)","Отдаёт по очереди все значения из вложенного генератора","Завершает генератор","Копирует x"]', 1, 'yield from делегирует работу другому итератору и избавляет от ручного цикла.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 4, 'Когда лучше генераторное выражение, чем генератор списка?', '["Когда нужен доступ по индексу","Когда результат нужно один раз свернуть, например sum(...), не храня всё в памяти","Когда данных мало","Никогда"]', 1, 'Ленивое выражение не создаёт список: значения рождаются по одному и сразу учитываются.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 24, 'theory', 'Квиз: send, throw и yield from');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 0, 'Что произойдёт при g.send(5) сразу после g = gen()?', '["Значение 5 запомнится","TypeError: нельзя отправлять непустое значение в только что созданный генератор","Генератор вернёт 5","Ничего: send игнорируется"]', 1, 'Перед первым yield принимать значение некому: сначала нужен next (или send(None)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 1, 'Что возвращает метод send?', '["Всегда None","Значение, которое только что отправили","Значение, отданное следующим yield","Состояние генератора"]', 2, 'send возобновляет генератор и возвращает то, что тот отдал на следующем yield.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 2, 'Что делает g.close()?', '["Удаляет генератор из памяти немедленно","Вбрасывает GeneratorExit в точку остановки, finally выполняются","Перезапускает генератор","Поднимает StopIteration у вызывающего"]', 1, 'GeneratorExit раскручивает стек генератора; если он попробует отдать значение — будет RuntimeError.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 3, 'Где лежит значение, которое генератор вернул через return?', '["В переменной цикла for","В результате next","В атрибуте value исключения StopIteration","В атрибуте gen.result"]', 2, 'Цикл for его отбрасывает, а yield from превращает в значение своего выражения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 24, 4, 'Что значит выражение result = yield from inner()?', '["Внешний генератор отдаёт все значения inner и получает его return в result","inner запускается в отдельном потоке","inner вызывается один раз и возвращает список","result — последнее отданное значение"]', 0, 'yield from делегирует работу inner (send/throw/close проходят насквозь) и возвращает его итог.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 25, 'theory', 'Квиз: функции высшего порядка');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 0, 'Что передаётся в sorted(words, key=len)?', '["Результат len(words)","Сама функция len, без вызова","Длина первого слова","Число"]', 1, 'Функция передаётся без скобок: sorted сам вызовет её на каждом элементе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 1, 'Чему равно (lambda a, b: a + b)(2, 3)?', '["5","23","Ошибка: у lambda нет return","None"]', 0, 'Тело лямбды — выражение, его значение и есть результат; return не нужен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 2, 'm = map(str, [1, 2]); list(m); list(m). Что вернёт второй list?', '["[''1'', ''2'']","[]","Ошибку","None"]', 1, 'map возвращает одноразовый итератор: после первого прохода он исчерпан.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 3, 'Что делает list(filter(None, [0, 1, '''', ''а'', []]))?', '["Оставляет только пустые значения","Убирает «ложные» значения, оставляя [1, ''а'']","Вызывает ошибку","Возвращает пустой список"]', 1, 'С None в роли функции filter отбирает элементы, истинные сами по себе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 25, 4, 'Почему в funcs = [lambda: i for i in range(3)] все лямбды вернут 2?', '["Баг интерпретатора","Лямбда помнит саму переменную i, а не её значение на момент создания","range вернул одну цифру","Лямбды нельзя хранить в списке"]', 1, 'Поздняя привязка: значение i берётся в момент вызова, когда цикл уже завершился.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 26, 'theory', 'Квиз: замыкания и декораторы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 0, 'Что такое замыкание?', '["Функция без аргументов","Вложенная функция, которая запомнила переменные внешней","Функция, закрывающая файл","Класс с методом __call__"]', 1, 'Замыкание уносит окружение: переменные внешней функции живут внутри вернувшейся внутренней.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 1, 'Зачем нужно слово nonlocal внутри вложенной функции?', '["Чтобы сделать переменную глобальной","Чтобы присваивать значение переменной внешней функции","Чтобы запретить изменение","Это то же, что return"]', 1, 'Без nonlocal присваивание создало бы новую локальную переменную.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 2, 'Что означает запись @timer над def square(x): ...?', '["Вызвать timer после square","square = timer(square)","Скопировать timer в square","Ничего особенного"]', 1, 'Знак @ — сокращение: имя функции получает результат вызова декоратора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 3, 'Что произойдёт, если обёртка декоратора вызовет func(*args, **kwargs), но не вернёт результат?', '["Всё будет работать","Декорированная функция будет возвращать None","Питон выдаст ошибку при описании","Результат удвоится"]', 1, 'Без return результат оригинала теряется: вызов вернёт None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 26, 4, 'Что делает @wraps(func) над внутренней обёрткой?', '["Ускоряет функцию","Копирует имя и докстринг исходной функции в обёртку","Запрещает вызов","Добавляет кеш"]', 1, 'wraps сохраняет __name__ и __doc__, чтобы отладка и справка видели настоящую функцию.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 27, 'theory', 'Квиз: functools и operator');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 0, 'Что даст reduce(operator.add, []) без начального значения?', '["0","None","TypeError: пустой набор без начального значения","[]"]', 2, 'Начальное значение защищает от пустого набора: с ним reduce вернул бы его.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 1, 'Что делает partial(int, base=2)?', '["Вызывает int сразу","Возвращает функцию с уже зафиксированным base=2","Переводит число в двоичную запись","Ничего"]', 1, 'partial фиксирует часть аргументов и возвращает новую функцию для остальных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 2, 'Какое условие обязательно для аргументов функции под @lru_cache?', '["Они должны быть числами","Они должны быть хешируемыми (не списки)","Их должно быть не больше двух","Они должны быть строками"]', 1, 'Кеш хранит аргументы в словаре, поэтому список передать нельзя: unhashable type.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 3, 'Что нужно описать в классе с @total_ordering?', '["Все шесть методов сравнения","__eq__ и один оператор порядка, например __lt__","Только __str__","Только __hash__"]', 1, 'Остальные сравнения декоратор достроит сам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 27, 4, 'Что вернёт itemgetter(''a'', ''b'')(d)?', '["Одно значение d[''a'']","Кортеж (d[''a''], d[''b''])","Словарь","Список ключей"]', 1, 'Несколько ключей дают кортеж значений — удобно для сортировки по нескольким полям.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 28, 'theory', 'Квиз: itertools');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 0, 'Что вернёт list(islice(count(10, 5), 3))?', '["[10, 15, 20]","[10, 5, 0]","[0, 5, 10]","Бесконечный список"]', 0, 'count(10, 5) бесконечно выдаёт 10, 15, 20, …; islice берёт первые три.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 1, 'Почему перед groupby данные обычно сортируют по тому же ключу?', '["Так быстрее","groupby группирует только соседние одинаковые элементы","Иначе не будет ошибок","Это требование Питона"]', 1, 'Без сортировки одна категория распадается на несколько групп.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 2, 'Чем accumulate отличается от reduce?', '["Ничем","accumulate отдаёт все промежуточные итоги, reduce — только последний","reduce ленивый","accumulate работает только с числами"]', 1, 'accumulate([1,2,3,4]) даёт [1, 3, 6, 10], а reduce(add, ...) — 10.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 3, 'Сколько элементов в list(combinations(range(5), 2))?', '["5","10","20","25"]', 1, 'Сочетания из 5 по 2: 5·4/2 = 10 (порядок в паре не важен).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 4, 'Чем zip_longest отличается от zip?', '["Он быстрее","Не отбрасывает хвост более длинного набора, а дополняет значением","Принимает только списки","Ничем"]', 1, 'zip останавливается на самом коротком, zip_longest доходит до самого длинного.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 29, 'theory', 'Квиз: декораторы глубже');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 0, '@a над @b над def f(): — в каком порядке применяются декораторы?', '["Сначала a, потом b","Одновременно","Порядок случайный","Сначала b оборачивает f, затем a оборачивает результат"]', 3, 'Читаем сверху вниз, применяем снизу вверх: f = a(b(f)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 1, 'Что даёт functools.wraps(func) на обёртке?', '["Ускоряет вызов","Копирует имя, документацию и кладёт __wrapped__ — ссылку на оригинал","Делает функцию асинхронной","Запрещает повторное декорирование"]', 1, 'Благодаря __wrapped__ inspect.signature показывает настоящие параметры, а не (*args, **kwargs).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 2, 'Почему @classmethod нужно ставить выше своего декоратора?', '["Так быстрее","Это только соглашение о стиле","Иначе @classmethod не сработает вообще","Ваша обёртка должна получить функцию, а не дескриптор classmethod"]', 3, 'classmethod, staticmethod и property — дескрипторы; нижний декоратор получает функцию, верхний — результат.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 3, 'Что не так с обычной обёрткой над async def функцией?', '["Вместо результата она получит корутину и не дождётся её","Ничего","Она вызовет функцию дважды","async-функции нельзя декорировать"]', 0, 'Нужна async-обёртка с await; универсальный декоратор выбирает по inspect.iscoroutinefunction.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 29, 4, 'Когда выполняется регистрирующий декоратор вроде @route(''/home'')?', '["При каждом вызове функции","Только при запуске сервера","При импорте модуля, когда функция определяется","Никогда сам, нужно вызвать вручную"]', 2, 'Декоратор срабатывает в момент определения, поэтому модуль нужно импортировать, иначе регистрация не произойдёт.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 30, 'theory', 'Квиз: интроспекция и inspect');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 0, 'Чем vars(obj) отличается от dir(obj)?', '["Ничем, это синонимы","vars возвращает собственные атрибуты экземпляра (его __dict__), а dir — все доступные имена","dir возвращает значения, vars — только имена","vars работает только с модулями"]', 1, 'dir отвечает «что доступно» (с унаследованным и специальным), vars — «что хранится именно здесь».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 1, 'Что вернёт getattr(obj, ''z'', None), если атрибута z нет?', '["AttributeError","None","Пустую строку","Значение ''z''"]', 1, 'Третий аргумент — значение по умолчанию: ошибку атрибута ловить не нужно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 2, 'Зачем нужен метод signature.bind(*args, **kwargs)?', '["Чтобы вызвать функцию","Чтобы изменить подпись","Чтобы узнать, какие значения достанутся каким параметрам, и получить TypeError при несоответствии","Чтобы скопировать функцию"]', 2, 'bind привязывает вызов к подписи; на нём строят проверку аргументов и внедрение зависимостей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 3, 'Где найти значения, захваченные вложенной функцией (замыкание)?', '["В __doc__","В __globals__","В __defaults__","В __closure__ — ячейки с cell_contents"]', 3, 'Имена свободных переменных лежат в __code__.co_freevars, а их значения — в ячейках __closure__.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 30, 4, 'Как правильно получить настоящие типы из аннотаций, если часть из них строки?', '["Через typing.get_type_hints (а в Python 3.14 — через annotationlib)","Прочитать __annotations__ напрямую","Выполнить eval над каждой строкой вручную","Через dir(func)"]', 0, 'Стандартные функции получения учитывают отложенные и строковые аннотации; словарь напрямую читать не стоит.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 31, 'theory', 'Квиз: метаклассы и __init_subclass__');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 0, 'Чему равно type(int)?', '["int","object","type","class"]', 2, 'Класс int — объект, а создаёт его type: «класс классов»; type(type) тоже type.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 1, 'Что делает вызов type(''P'', (), {})?', '["Возвращает тип значения","Создаёт новый класс с именем P без родителей и атрибутов","Создаёт экземпляр класса P","Поднимает ошибку"]', 1, 'С тремя аргументами type создаёт класс: имя, кортеж родителей и словарь атрибутов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 2, 'Что выполняется раньше: __new__ класса или __call__ метакласса?', '["__new__ класса","Их порядок случаен","__call__ метакласса: он и вызывает __new__ и __init__","__init__ класса"]', 2, 'A() вызывает type(A).__call__, а тот уже по очереди запускает A.__new__ и A.__init__.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 3, 'Когда вызывается __init_subclass__ родителя?', '["При создании экземпляра потомка","При каждом вызове метода потомка","При импорте родителя","При определении каждого нового класса-потомка"]', 3, 'Хук срабатывает один раз на потомка в момент создания класса и получает именованные аргументы из class-оператора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 31, 4, 'Что лучше выбрать, если нужно просто зарегистрировать всех потомков базового класса?', '["Метакласс","Хук __init_subclass__","Подмену type","Копирование классов вручную"]', 1, 'Хук проще метакласса: не нужен новый класс и нет конфликтов метаклассов.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 32, 'theory', 'Квиз: ast, eval, exec и dis');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 0, 'Что делает ast.literal_eval(''[1, 2, 3]'')?', '["Выполняет произвольный код","Безопасно разбирает литерал и возвращает список","Считает сумму чисел","Поднимает SyntaxError"]', 1, 'literal_eval понимает только литералы (числа, строки, списки, словари, множества, кортежи) и не вызывает функции.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 1, 'Чем compile отличается от exec?', '["Ничем","compile выполняет код, exec — только разбирает","compile лишь превращает текст в объект кода, который потом можно выполнить много раз","exec работает только с файлами"]', 2, 'compile возвращает объект кода; eval/exec его выполняют, и повторного разбора текста не требуется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 2, 'Как безопасно вычислить пользовательское арифметическое выражение?', '["eval с пустым словарём имён","Убрать из строки слова import и exec","Разобрать в дерево ast и разрешить только известные узлы (числа и операции)","Запустить в отдельном потоке"]', 2, 'Фильтры строк обходятся, а белый список узлов опирается на грамматику языка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 3, 'Что возвращает метод visit_BinOp у NodeTransformer?', '["Всегда None","Строку исходного кода","Результат вычисления выражения","Новый узел, который заменит старый (или None для удаления)"]', 3, 'NodeTransformer подменяет узлы; после изменений нужен fix_missing_locations, а ast.unparse вернёт текст.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 32, 4, 'Зачем нужен модуль dis?', '["Чтобы ускорять программу","Чтобы читать команды стековой машины и понимать, во что превращается код","Чтобы подписывать код","Чтобы отключать оптимизации"]', 1, 'dis.dis печатает байт-код; набор команд меняется от версии к версии, поэтому в рабочем коде на имена не опираются.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 33, 'theory', 'Квиз: коллекции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 0, 'c = Counter("aab"). Чему равно c["z"]?', '["KeyError","0","None","1"]', 1, 'У счётчика отсутствующий ключ даёт ноль, а не ошибку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 1, 'd = defaultdict(list); d[''x''] — что стало со словарём?', '["Ничего: ключа нет, вернулась ошибка","Появилась запись ''x'': []","Питон выдал None","Словарь очистился"]', 1, 'Даже чтение отсутствующего ключа создаёт запись значением по умолчанию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 2, 'Почему для очереди лучше deque, чем список?', '["deque короче в записи","У deque быстрые операции на обоих концах, у списка — удаление в начале сдвигает все элементы","deque хранит меньше данных","Список нельзя использовать как очередь"]', 1, 'popleft у deque работает за постоянное время, а list.pop(0) сдвигает остальные элементы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 3, 'Что гарантирует куча heapq?', '["Список полностью отсортирован","Наименьший элемент всегда лежит в начале (индекс 0)","Элементы идут по убыванию","Все элементы уникальны"]', 1, 'Куча упорядочена лишь частично: гарантирован только минимум в начале.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 33, 4, 'Что вернёт bisect.bisect_left([10, 20, 20, 30], 20)?', '["0","1","2","3"]', 1, 'Позиция перед первым вхождением значения 20 — индекс 1 (bisect_right вернул бы 3).');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 34, 'theory', 'Квиз: числа и случайность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 0, 'Почему 0.1 + 0.2 == 0.3 даёт False?', '["Баг Питона","Дробные числа хранятся в двоичном виде с погрешностью","Нужно писать 0,1","Сравнение не работает для дробных"]', 1, 'Десятая часть в двоичной системе — бесконечная дробь, поэтому результат приблизительный. Сравнивайте через math.isclose.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 1, 'Чему равно round(2.5)?', '["3","2","2.5","Ошибка"]', 1, 'round округляет к ближайшему чётному: для 2.5 — это 2, для 3.5 — 4.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 2, 'Как правильно создать Decimal для 0.1?', '["Decimal(0.1)","Decimal(\"0.1\")","Decimal(1 / 10)","Decimal.of(0.1)"]', 1, 'Из строки — точно; из float число уже содержит погрешность.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 3, 'Что делает random.seed(42)?', '["Делает числа безопасными","Фиксирует начало последовательности: результаты повторяются","Генерирует число 42","Перемешивает список"]', 1, 'С одним и тем же зерном random выдаёт одну и ту же «случайную» последовательность — удобно для тестов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 4, 'Что нужно использовать для генерации пароля или токена?', '["random","secrets","statistics","math"]', 1, 'random предсказуем; secrets берёт случайность у операционной системы и подходит для безопасности.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 35, 'theory', 'Квиз: дата и время');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 0, 'Что даёт вычитание двух дат date(2025, 1, 1) - date(2024, 12, 25)?', '["Число 7","Объект timedelta: 7 days","Новую дату","Ошибку"]', 1, 'Разность дат — timedelta; у него есть .days и .total_seconds().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 1, 'Почему в timedelta нет месяцев и лет?', '["Их забыли добавить","Их длина не постоянна: месяцы бывают по 28–31 дню","Они хранятся отдельно","Это ограничение Windows"]', 1, 'Поэтому «плюс месяц» считают вручную или внешними библиотеками.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 2, 'Какой формат лучше всего подходит для хранения даты в файле или базе?', '["05.03.2024","3/5/24","2024-03-05 (ISO)","5 марта 2024"]', 2, 'ISO-запись однозначна и сортируется как текст в порядке времени.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 3, 'Что произойдёт при сравнении наивного datetime с осведомлённым (с часовым поясом)?', '["Сравнение сработает по UTC","TypeError: нельзя сравнивать offset-naive и offset-aware","Вернётся None","Питон добавит пояс сам"]', 1, 'Смешивать их нельзя: нужно привести оба к одному виду.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 35, 4, 'Как правильно замерять время работы кода?', '["time.time() до и после","time.perf_counter() до и после","datetime.now() до и после","sleep()"]', 1, 'perf_counter — самый точный таймер и не зависит от перевода системных часов.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 36, 'theory', 'Квиз: регулярные выражения');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 0, 'Что означает шаблон r"\d{3}"?', '["Ровно три цифры подряд","Цифру 3","От нуля до трёх цифр","Три любых символа"]', 0, '\d — цифра, {3} — ровно три повторения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 1, 'Чем re.match отличается от re.search?', '["Ничем","match проверяет только начало строки, search ищет в любом месте","search быстрее","match ищет все совпадения"]', 1, 'Для поиска «где угодно» нужен search; match привязан к началу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 2, 'Что вернёт re.search(r"<.*>", "<a><b>").group()?', '["<a>","<a><b>","<b>","None"]', 1, 'Квантификатор * жадный и берёт максимум; для минимума нужно .*?');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 3, 'Зачем шаблоны записывают в сырых строках r"..."?', '["Так быстрее","Чтобы Питон не обрабатывал обратные косые черты","Чтобы работали русские буквы","Это обязательное требование модуля re"]', 1, 'Без r-префикса «\d» пришлось бы писать как «\\d».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 36, 4, 'Что нужно сделать перед обращением к m.group(1), если m = re.search(...)?', '["Ничего","Проверить, что m не None: при отсутствии совпадения поиск вернёт None","Вызвать re.compile","Преобразовать в список"]', 1, 'Если совпадения нет, m равно None, и вызов метода упадёт с AttributeError.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 37, 'theory', 'Квиз: программы и среда');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 0, 'Куда принято отправлять сообщения об ошибках, чтобы их можно было отделить от данных?', '["В stdout","В stderr","В файл data.txt","В sys.argv"]', 1, 'print(..., file=sys.stderr): при перенаправлении вывода ошибки остаются на экране, а данные уходят в файл.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 1, 'Что вернёт argparse, если пользователь передал недопустимое значение?', '["Тихо проигнорирует","Напечатает сообщение об ошибке и завершит программу с кодом 2","Заменит значением по умолчанию","Вернёт None"]', 1, 'parse_args сам сообщает о проблеме и вызывает sys.exit(2).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 2, 'Какой уровень логирования показывает только предупреждения и серьёзнее?', '["DEBUG","INFO","WARNING","NOTSET"]', 2, 'Уровни: DEBUG < INFO < WARNING < ERROR < CRITICAL; сообщения ниже настроенного уровня не выводятся.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 3, 'Почему в subprocess.run команду передают списком и не включают shell=True?', '["Так быстрее","Данные пользователя не смогут превратиться в команды оболочки","Список короче строки","shell=True запрещён"]', 1, 'shell=True со строкой из чужого ввода — классическая уязвимость инъекции команд.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 37, 4, 'Что означает проверка if __name__ == "__main__"?', '["Файл называется main","Код под ней выполняется только при запуске файла как программы, но не при импорте","Код выполняется всегда","Запускает тесты"]', 1, 'При импорте модуля __name__ равно имени модуля, а не «__main__».');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 38, 'theory', 'Квиз: данные и типы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 0, 'Что автоматически создаёт декоратор @dataclass?', '["Только __str__","Конструктор, __repr__ и сравнение по полям","Базу данных","Свойства для всех полей"]', 1, 'Это и есть главный выигрыш: вместо двадцати строк шаблонного кода — перечень полей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 1, 'Как правильно задать пустой список по умолчанию в датаклассе?', '["items: list = []","items: list = field(default_factory=list)","items = list","items: list = None"]', 1, 'Изменяемые умолчания запрещены; default_factory создаёт новый список для каждого экземпляра.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 2, 'Что произойдёт при Color(9), если в Enum нет члена со значением 9?', '["Вернётся None","ValueError: 9 is not a valid Color","Создастся новый член","Вернётся первый член"]', 1, 'Перечисление защищает от несуществующих значений.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 3, 'Проверяет ли Питон подсказки типов во время выполнения?', '["Да, всегда","Нет: их читают человек, редактор и анализатор (mypy)","Только для int","Только в датаклассах"]', 1, 'add(''a'', ''b'') с подсказкой int спокойно вернёт ''ab'' — проверяет это статический анализатор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 4, 'a = [[1, 2], [3]]; b = copy.copy(a); a[0].append(9). Что в b[0]?', '["[1, 2]","[1, 2, 9]","[9]","Ошибка"]', 1, 'copy.copy делает поверхностную копию: вложенные списки остаются общими. Для независимости нужен deepcopy.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 39, 'theory', 'Квиз: тестирование');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 0, 'Какое свойство важно для хорошего теста?', '["Он зависит от результата соседнего теста","Он маленький, быстрый, независимый и проверяет одну идею","Он использует настоящую сеть","Он длиннее проверяемого кода"]', 1, 'Независимые быстрые тесты падают только тогда, когда сломан проверяемый код.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 1, 'Для чего нужен метод setUp в TestCase?', '["Запускает программу","Готовит чистое окружение перед каждым тестом","Удаляет тесты","Считает покрытие"]', 1, 'setUp выполняется перед каждым test_*, поэтому тесты не влияют друг на друга.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 2, 'Как проверить, что функция при неверных данных поднимает ValueError?', '["assertEqual(f(), ValueError)","with self.assertRaises(ValueError): f(...)","try ... except: pass","assert f() is None"]', 1, 'assertRaises сообщит о сбое, если исключения не будет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 3, 'Что делает unittest.mock.patch?', '["Исправляет баги автоматически","Временно подменяет объект (например, функцию сети) на мок на время теста","Ускоряет тесты","Создаёт тестовые данные"]', 1, 'После теста подмена снимается; так код изолируют от сети, времени и случайности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 39, 4, 'Что означает цикл «красный — зелёный — рефакторинг»?', '["Раскраска вывода","Сначала падающий тест, затем минимальный код, затем наведение порядка при зелёных тестах","Три вида ошибок","Порядок запуска файлов"]', 1, 'Это подход «тест раньше кода» (TDD): маленькие шаги, каждый подтверждён тестом.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 40, 'theory', 'Квиз: абстрактные классы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 0, 'Что произойдёт при создании экземпляра класса с нереализованным @abstractmethod (класс унаследован от ABC)?', '["Метод вернёт None","TypeError при создании экземпляра","Ошибка только при вызове метода","Ничего, метод создастся автоматически"]', 1, 'ABCMeta хранит имена абстрактных методов; пока множество не пусто, создание экземпляра отклоняется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 1, 'Вы повесили @abstractmethod, но не унаследовали класс от ABC. Что будет?', '["Класс нельзя будет создать","Питон поднимет ошибку определения","Декоратор молча проигнорируется, и экземпляр создастся","Метод станет приватным"]', 2, 'Проверку делает метакласс ABCMeta — без него абстрактные методы ничего не запрещают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 2, 'Как правильно объявить абстрактное свойство?', '["@abstractmethod над @property","@property над @abstractmethod","Только через метакласс","Свойства абстрактными быть не могут"]', 1, '@abstractmethod должен быть ближе всего к функции, @property — над ним.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 3, 'Для чего нужен ABC.register(Cls)?', '["Чтобы унаследовать методы","Чтобы запретить класс","Чтобы считать Cls подклассом без наследования (isinstance подтвердит)","Чтобы создать экземпляр"]', 2, 'Виртуальные подклассы связывают чужие классы с вашей иерархией.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 40, 4, 'Что нужно реализовать, чтобы унаследоваться от collections.abc.Sequence?', '["__len__ и __getitem__ — остальное будет готово","Все методы списка","Только __iter__","Только __contains__"]', 0, 'Sequence даёт перебор, in, count, index и reversed на основе __len__ и __getitem__.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 41, 'theory', 'Квиз: протоколы и обобщения');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 0, 'Проверяет ли Питон подсказки типов при выполнении программы?', '["Да, всегда","Только для функций с декоратором","Нет: их читают редакторы и проверяющие программы (mypy, pyright)","Только в режиме отладки"]', 2, 'Подсказки типов — метаданные; интерпретатор их не навязывает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 1, 'Чем Protocol отличается от абстрактного класса?', '["Ничем","Подойдёт любой объект с нужными методами — наследование не требуется","Он запрещает наследование","Он работает только во время выполнения"]', 1, 'Протокол — структурная подтипизация: форма важнее предка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 2, 'Что проверяет isinstance(obj, P) для @runtime_checkable протокола P?', '["Только наличие нужных атрибутов и методов по именам","Подписи методов и типы значений","Что obj унаследован от P","Ничего"]', 0, 'Проверка поверхностная: подписи и типы остаются на совести проверяющей программы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 3, 'Что даёт TypeVar в def first(items: Sequence[T]) -> T?', '["Ограничивает T только числами","Делает функцию медленнее","Связывает тип элементов входа с типом результата","Включает проверку при запуске"]', 2, 'Для списка чисел результат — число, для списка строк — строка; без TypeVar связь потерялась бы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 41, 4, 'Как правильно подсказать тип параметра, который функция только перебирает?', '["list[Any]","object","Any","Iterable[T]"]', 3, 'Принимайте наименее требовательный тип: тогда подойдут кортежи, множества и генераторы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 42, 'theory', 'Квиз: множественное наследование и MRO');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 0, 'Каким будет MRO у D(B, C), если B и C наследуют от A?', '["D, A, B, C, object","D, B, A, C, object","D, C, B, A, object","D, B, C, A, object"]', 3, 'C3: класс перед родителями, порядок баз сохранён, общий предок A — после обоих потомков.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 1, 'Что на самом деле делает super()?', '["Всегда вызывает непосредственного родителя","Вызывает следующий класс в MRO у типа самого объекта","Вызывает object","Создаёт копию объекта"]', 1, 'Поэтому внутри B объекта D(B, C) super() передаёт управление C, а не A.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 2, 'Что произойдёт при class C(A, B), если B наследует от A?', '["TypeError: нельзя построить согласованный MRO","Класс создастся, A выполнится дважды","Питон переставит базы","Класс создастся, но без методов A"]', 0, 'Требования C3 несовместимы: A нельзя поставить раньше его потомка B.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 3, 'Где принято ставить миксины в списке баз?', '["Справа от основного базового","Слева от основного базового","Порядок не важен","Миксины нельзя использовать с super()"]', 1, 'Слева — тогда их методы раньше в MRO и могут обернуть метод основного класса через super().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 42, 4, 'Зачем __init__ миксина принимает **kwargs и вызывает super().__init__(**kwargs)?', '["Для скорости","Чтобы цепочка init прошла по всему MRO, а лишние параметры дошли до нужного класса","Чтобы запретить аргументы","Чтобы вызвать object дважды"]', 1, 'Кооперативное наследование: каждый берёт своё и передаёт остальное дальше.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 43, 'theory', 'Квиз: конкурентность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 0, 'Чем конкурентность отличается от параллельности?', '["Ничем","Конкурентность — задачи идут вперемешку, параллельность — одновременно на разных ядрах","Параллельность медленнее","Конкурентность — это только потоки"]', 1, 'Конкурентность — организация нескольких задач; параллельность — их одновременное исполнение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 1, 'Какие задачи потоки в Питоне ускоряют?', '["Чистые вычисления","Ожидание ввода-вывода: сеть, диск, сон","Любые","Никакие"]', 1, 'GIL отпускается на ожидании, поэтому ожидания идут одновременно; вычисления остаются последовательными.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 2, 'Зачем нужен Lock при изменении общего счётчика из нескольких потоков?', '["Ускоряет программу","Не даёт потокам перезаписать чужие изменения: «прочитать-прибавить-записать» не неделимо","Нужен только для чтения","Блокирует GIL"]', 1, 'Без замка возникает состояние гонки и счётчик получается меньше ожидаемого.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 3, 'Что хранит объект Future, если в задаче произошла ошибка?', '["Ничего","Исключение: оно поднимется при вызове result()","Значение None","Код возврата"]', 1, 'Фьючер сохраняет исключение и поднимает его в том месте, где вы читаете результат.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 43, 4, 'Что лучше выбрать для тяжёлых вычислений на нескольких ядрах?', '["Потоки","Процессы (ProcessPoolExecutor)","Очередь","Event"]', 1, 'У каждого процесса свой интерпретатор и свой GIL, поэтому расчёты действительно идут параллельно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 44, 'theory', 'Квиз: asyncio');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 0, 'Что вернёт вызов async-функции hello() без await и без asyncio.run?', '["Результат функции","Объект корутины: тело ещё не выполнялось","None","Ошибку синтаксиса"]', 1, 'Корутина — заготовка работы: её нужно ждать через await или запустить через asyncio.run.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 1, 'Что происходит при time.sleep(1) внутри корутины?', '["Корутина спит, остальные работают","Замораживается весь цикл событий: все корутины стоят","Питон выдаёт ошибку","Ничего особенного"]', 1, 'Блокирующий вызов не уступает управление; нужно asyncio.sleep или вынос в поток.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 2, 'Три задачи по 0,2 с создали через create_task и дождались. Сколько примерно займёт ожидание?', '["0,6 с","около 0,2 с","0,4 с","0 с"]', 1, 'Ожидания накладываются: задачи идут конкурентно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 3, 'В каком порядке gather возвращает результаты?', '["В порядке завершения","В порядке передачи корутин","По убыванию","Случайно"]', 1, 'Порядок результатов совпадает с порядком аргументов, независимо от того, кто закончил раньше.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 44, 4, 'Что нужно делать с CancelledError, который пришёл в корутину?', '["Подавить и продолжить","Не глотать: пропустить дальше (убрать за собой в finally)","Вызвать exit()","Превратить в ValueError"]', 1, 'Подавленная отмена делает задачу неостановимой.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 45, 'theory', 'Квиз: asyncio на практике');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 0, 'Какой порт указывают в start_server, чтобы система выбрала любой свободный?', '["80","0","-1","None"]', 1, 'Порт 0 означает «любой свободный»; реальный номер берут из server.sockets[0].getsockname().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 1, 'Почему повторы запросов делают с растущей задержкой (backoff)?', '["Так красивее","Мгновенные повторы добивают перегруженный сервер; пауза даёт ему восстановиться","Это требование asyncio","Чтобы тратить время"]', 1, 'Задержку обычно удваивают и добавляют случайность, чтобы клиенты не стучались одновременно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 2, 'Какой класс нужен, чтобы писать тесты-корутины (async def test_...)?', '["unittest.TestCase","unittest.IsolatedAsyncioTestCase","asyncio.TestCase","doctest.AsyncCase"]', 1, 'Его методы выполняются на настоящем цикле событий, и внутри можно писать await.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 3, 'Что произойдёт, если в async-обработчике веб-сервера вызвать time.sleep(5)?', '["Заснёт только этот запрос","Весь сервер остановится на 5 секунд","Питон выдаст ошибку","Ничего"]', 1, 'Блокирующий вызов замораживает цикл событий; ожидание нужно отдавать await, блокировку — потокам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 4, 'Для чего нужны contextvars в асинхронном коде?', '["Для ускорения","Чтобы у каждой задачи было своё значение переменной (например, номер запроса)","Для работы с сетью","Для таймаутов"]', 1, 'Каждая задача получает копию контекста, и изменения внутри неё не видны другим.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 46, 'theory', 'Квиз: асинхронные итераторы и менеджеры контекста');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 0, 'Какое исключение сообщает о конце асинхронного итератора?', '["StopIteration","StopAsyncIteration","EOFError","CancelledError"]', 1, 'Корутина __anext__ поднимает StopAsyncIteration, когда элементов больше нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 1, 'Что нельзя сделать внутри асинхронного генератора?', '["Использовать await","Использовать yield","Вернуть значение через return","Использовать try/finally"]', 2, 'return со значением — SyntaxError; пустой return разрешён.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 2, 'Что произойдёт с finally внутри генератора, если выйти из async for через break?', '["Выполнится сразу","Поднимется ошибка","Никогда не выполнится","Не выполнится сразу: генератор остаётся приостановленным, пока его не закроют"]', 3, 'Закройте генератор вызовом aclose() или блоком async with aclosing(...).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 3, 'Что делает декоратор @asynccontextmanager?', '["Делает функцию синхронной","Запускает функцию в потоке","Превращает асинхронный генератор в асинхронный менеджер контекста","Кэширует результат"]', 2, 'До yield — открытие, после — закрытие, а try/finally гарантирует уборку при ошибке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 4, 'Можно ли подавлять asyncio.CancelledError широким except?', '["Нельзя: отмена обязана пройти наружу, иначе задачу не остановить","Нужно: так программа устойчивее","Можно, если логируем","Можно только в тестах"]', 0, 'Перехватывайте конкретные ошибки, а после обработки поднимайте отмену дальше.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 47, 'theory', 'Квиз: память, сборщик мусора и слабые ссылки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 0, 'Когда в CPython уничтожается объект, у которого нет циклических ссылок?', '["В момент следующего запуска сборщика мусора","При завершении программы","Сразу, когда его счётчик ссылок станет равен нулю","Через минуту после последнего использования"]', 2, 'Счётчик ссылок освобождает объект немедленно; сборщик нужен лишь для циклов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 1, 'Зачем нужен циклический сборщик мусора (модуль gc)?', '["Чтобы освобождать любые объекты вместо счётчика","Чтобы находить и освобождать недостижимые циклы объектов","Чтобы ускорять программу","Чтобы закрывать файлы"]', 1, 'В цикле счётчики не падают до нуля, поэтому нужен отдельный механизм.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 2, 'Что возвращает weakref.ref(obj)(), если объект уже удалён?', '["None","Исключение ReferenceError","Пустой объект","Последнее значение"]', 0, 'Вызов слабой ссылки даёт объект, если он жив, или None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 3, 'Почему не стоит полагаться на __del__ для закрытия ресурсов?', '["Он не работает в CPython","Момент вызова зависит от реализации, а исключения в нём лишь печатаются","Он слишком быстрый","Он вызывается дважды"]', 1, 'Используйте менеджеры контекста и weakref.finalize.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 4, 'Чем deepcopy отличается от copy?', '["Скорость","deepcopy копирует и вложенные объекты, запоминая уже скопированное в memo","deepcopy копирует только ключи","Ничем для списков"]', 1, 'memo позволяет deepcopy корректно обходить циклические структуры.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 48, 'theory', 'Квиз: байт-код, GIL и потоки без GIL');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 0, 'Что хранится в каталоге __pycache__?', '["Исходные тексты модулей","Резервные копии файлов","Кэш скомпилированного байт-кода (.pyc) с меткой версии интерпретатора","Журнал ошибок"]', 2, 'Модуль компилируется один раз, а при изменении исходника кэш пересоздаётся.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 1, 'Что даёт специализирующий адаптивный интерпретатор (3.11+)?', '["Он убирает GIL","Он компилирует всё в машинный код заранее","Он ускоряет только ввод-вывод","Он заменяет часто выполняемые команды быстрыми версиями под устойчивые типы"]', 3, 'При смене типов специализация откатывается, поэтому в горячих местах типы лучше держать устойчивыми.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 2, 'Почему потоки не ускоряют вычисления на процессоре в CPython со включённым GIL?', '["Потоки запрещены","В каждый момент байт-код выполняет только один поток","Потоки используют только одно ядро памяти","Из-за асинхронности"]', 1, 'Для CPU-задач берут процессы, расширения на C, субинтерпретаторы или сборку без GIL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 3, 'Делает ли GIL код потокобезопасным?', '["Да, полностью","Только для строк","Нет: x += 1 состоит из нескольких команд, и потоки могут переключиться между ними","Только для чисел"]', 2, 'Составные операции нужно защищать Lock или передавать данные через Queue.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 48, 4, 'Как узнать, включён ли GIL в запущенном интерпретаторе (3.13+)?', '["sys._is_gil_enabled()","os.gil()","threading.gil_state()","gc.gil()"]', 0, 'А sysconfig.get_config_var(''Py_GIL_DISABLED'') показывает тип сборки (1 — свободные потоки).');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 49, 'theory', 'Квиз: производительность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 0, 'Что нужно сделать перед оптимизацией?', '["Измерить и найти узкое место профилировщиком","Переписать код на C","Убрать все функции","Включить отладочный режим"]', 0, 'Оптимизация по догадке тратит время на неважное и портит читаемость.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 1, 'Что даёт минимум из нескольких серий timeit.repeat?', '["Среднее по всем запускам","Время самого медленного запуска","Оценку с минимальным шумом от других процессов","Ничего"]', 2, 'Шум только увеличивает время, поэтому минимум ближе всего к истинной стоимости кода.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 2, 'Что показывает столбец tottime в cProfile?', '["Время вместе с вложенными вызовами","Время самой функции без вложенных вызовов","Число вызовов","Время запуска программы"]', 1, 'cumtime — время вместе с вызванными функциями, а ncalls — число вызовов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 3, 'Почему @functools.cache делает рекурсивный fib быстрым?', '["Он компилирует функцию в машинный код","Он запускает вызовы параллельно","Он отключает рекурсию","Он запоминает результаты, и каждое значение считается один раз"]', 3, 'Без кэша число вызовов растёт экспоненциально, с кэшем — линейно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 49, 4, 'Что утверждает закон Амдала?', '["Параллельный код всегда ускоряется во столько раз, сколько ядер","Ускорение ограничено долей работы, которую нельзя распараллелить","Потоки быстрее процессов","Кэш всегда помогает"]', 1, 'Если 10% работы последовательны, то больше чем в 10 раз ускорить не получится.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 50, 'theory', 'Квиз: пакеты, окружения и uv');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 0, 'Зачем нужно виртуальное окружение?', '["Чтобы программа работала быстрее","Чтобы изолировать зависимости проекта от системы и других проектов","Чтобы шифровать код","Чтобы запускать программу без Питона"]', 1, 'У каждого проекта — свой интерпретатор и свои пакеты; в системный Питон проектные библиотеки не ставят.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 1, 'Что хранит файл блокировки (например, uv.lock)?', '["Только прямые зависимости без версий","Исходный код проекта","Точные версии и контрольные суммы всех пакетов, включая транзитивные","Пароли и ключи"]', 2, 'Благодаря ему сборка воспроизводима на любой машине.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 2, 'Где в современном проекте описывают имя, версию, зависимости и настройки инструментов?', '["В pyproject.toml","В setup.cfg","В requirements.txt","В README.md"]', 0, 'pyproject.toml заменил россыпь setup.py, setup.cfg и requirements.txt.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 3, 'Что означает условие версии ~=1.4.2?', '["Ровно 1.4.2","Любая версия, кроме 1.4.2","Не больше 1.4.2","Совместимый выпуск: >=1.4.2 и ==1.4.*"]', 3, 'Разрешаются исправления внутри ветки 1.4, но не 1.5.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 50, 4, 'Почему зависимости в Dockerfile ставят до копирования кода?', '["Так требует Питон","Зависимости меняются реже кода и кэшируются отдельным слоем","Так образ получается больше","Иначе не запустится uv"]', 1, 'При изменении кода слой с зависимостями не пересобирается.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 51, 'theory', 'Квиз: качество кода и шаблоны');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 0, 'Зачем в проекте нужен автоматический форматтер (black, ruff format)?', '["Чтобы ускорить программу","Чтобы споры о стиле исчезли: код оформляется одинаково для всей команды","Чтобы проверять типы","Чтобы удалять комментарии"]', 1, 'Форматтер и линтер подключают к хукам перед коммитом и к CI.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 1, 'Что означает 100% покрытие кода тестами?', '["Ошибок в коде нет","Все строки выполнялись при тестах, но правильность это не доказывает","Все функции аннотированы","Тесты работают быстро"]', 1, 'Без проверок (assert) покрытие бесполезно: ориентируйтесь на сценарии и границы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 2, 'Как в Питоне проще всего реализовать шаблон «Стратегия»?', '["Только через классы и наследование","Нужна специальная библиотека","Невозможно","Передать функцию параметром"]', 3, 'Функции — полноправные значения, поэтому стратегия сводится к параметру-функции.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 3, 'О чём говорит принцип единственной ответственности?', '["У функции или класса должна быть одна причина для изменения","В проекте должен быть один класс","Все функции должны быть короче строки","Исключения запрещены"]', 0, 'Если функция читает, считает и пишет, у неё три причины меняться.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 4, 'С чего начинать рефакторинг?', '["С переписывания всего с нуля","С переименования всех файлов","С тестов, которые фиксируют текущее поведение","С отключения линтера"]', 2, 'Затем — маленькие шаги и проверки после каждого.');
